def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """ Given a string s and an integer k, partition s into k substrings such that the sum 
    of the number of letter changes required to turn each substring into a semi-palindrome 
    is minimized. Return the minimum number of letter changes required.

    A string is a semi-palindrome if:
    - It has length >= 2, AND
    - There exists a positive integer d such that 1 <= d < len and len % d == 0, AND
    - Taking indices that have the same modulo by d forms a palindrome.

    For example: "aa", "aba", "adbgad", and "abab" are semi-palindromes.
    "a", "ab", and "abca" are not semi-palindromes.

    Args:
        s: A string consisting only of lowercase English letters (2 <= len(s) <= 200)
        k: Number of substrings to partition into (1 <= k <= len(s) / 2)

    Returns:
        The minimum number of letter changes required to make all k substrings semi-palindromes.

    >>> min_changes_for_semi_palindromes("abcac", 2)
    1
    >>> min_changes_for_semi_palindromes("abcdef", 2)
    2
    >>> min_changes_for_semi_palindromes("aabbaa", 3)
    0
    """
    n = len(s)
    if k == 1:
        changes = 0
        for d in range(1, n):
            if n % d == 0:
                is_semi_palindrome = True
                for i in range(n // d):
                    for j in range(1, d):
                        if s[i * d + j] != s[i * d + d - 1 - j]:
                            is_semi_palindrome = False
                            break
                    if not is_semi_palindrome:
                        break
                if is_semi_palindrome:
                    return 0
        for i in range(n // 2):
            if s[i] != s[n - 1 - i]:
                changes += 1
        return changes

    dp = {}

    def solve(index, partitions):
        if (index, partitions) in dp:
            return dp[(index, partitions)]

        if index == n:
            if partitions == k:
                return 0
            else:
                return float('inf')

        if partitions > k:
            return float('inf')

        min_cost = float('inf')

        for j in range(index, n):
            substring = s[index:j+1]

            cost = 0

            if len(substring) >= 2:


                is_semi_palindrome = False
                for d in range(1, len(substring)):
                    if len(substring) % d == 0:
                        temp_is_semi_palindrome = True
                        for i in range(len(substring) // d):
                            for j in range(1, d):
                                if substring[i * d + j] != substring[i * d + d - 1 - j]:
                                    temp_is_semi_palindrome = False
                                    break
                            if not temp_is_semi_palindrome:
                                break
                        if temp_is_semi_palindrome:
                            is_semi_palindrome = True
                            break

                if not is_semi_palindrome:
                    for i in range(len(substring) // 2):
                        if substring[i] != substring[len(substring) - 1 - i]:
                            cost += 1

            min_cost = min(min_cost, cost + solve(j + 1, partitions + 1))

        dp[(index, partitions)] = min_cost
        return min_cost

    return solve(0, 0)
