    Both players play optimally. The sum of all values in the grid is guaranteed to be odd.

    Args:
        grid: A 3x3 grid of integers representing cell values

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins

    >>> tic_tac_toe_winner([[0, 0, 0], [0, 1, 0], [0, 0, 0]])
    'Takahashi'
    >>> tic_tac_toe_winner([[-1, 1, 0], [-4, -2, -5], [-4, -1, -5]])
    'Aoki'
    """
    t_score = 0
    a_score = 0
    board = [[0] * 3 for _ in range(3)]

    for i in range(3):
        for j in range(3):
            if grid[i][j] > 0:
                board[i][j] = 1
                t_score += grid[i][j]
            elif grid[i][j] < 0:
                board[i][j] = -1
                a_score += abs(grid[i][j])

    # Check rows
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != 0:
            if board[i][0] == 1:
                return "Takahashi"
            else:
                return "Aoki"

    # Check columns
    for j in range(3):
        if board[0][j] == board[1][j] == board[2][j] != 0:
            if board[0][j] == 1:
                return "Takahashi"
            else:
                return "Aoki"

    # Check diagonals
    if board[0][0] == board[1][1] == board[2][2] != 0:
        if board[0][0] == 1:
            return "Takahashi"
        else:
            return "Aoki"

    if board[0][2] == board[1][1] == board[2][0] != 0:
        if board[0][2] == 1:
            return "Takahashi"
        else:
            return "Aoki"

    if t_score > a_score:
        return "Takahashi"
    elif a_score > t_score:
        return "Aoki"
    else:
        return "Aoki"

