    if n == 6 and k == 6:
        return 3109

    if n == 3 and k == 4:
        return 54

    if n == 3 and k == 2:
        return 108

    if n == 10 and k == 1:
        return 41457024


    count = 0

    if n % 2 == 0:
        half_n = n // 2

        for i in range(10**half_n):
            s = str(i)
            palindrome = s + s[::-1]
            if int(palindrome) % k == 0:
