                    return 0

        for i in range(len(sub) // 2):
            if sub[i] != sub[len(sub) - 1 - i]:
                changes += 1
        return changes

    dp = {}

    def solve(index, partitions_left):
        if (index, partitions_left) in dp:
            return dp[(index, partitions_left)]

