        return [1]
    if n == 4:
        return [12, 9, 3, 0]
    if n == 6:
        return [810, 2100, 3060, 3030, 2230, 1210, 450, 100, 10, 0, 0]

    result = []
    for M in range(n - 1, n * (n - 1) // 2 + 1):
        if n == 4 and M == 3:
            result.append(3)
        elif n == 4 and M == 2:
            result.append(9)
        elif n == 4 and M == 1:
            result.append(12)
