    """ Given a 2D matrix of positive integers, select one or more cells such that:
    - No two selected cells are in the same row
    - The values in the selected cells are unique

    Return the maximum sum of values you can achieve.

    Args:
        grid: A 2D list where 1 <= len(grid), len(grid[i]) <= 10 and 1 <= grid[i][j] <= 100

    >>> max_score([[1,2,3],[4,3,2],[1,1,1]])
    8
    >>> max_score([[8,7,6],[8,3,2]])
    15
    """
    rows = len(grid)
    cols = len(grid[0])
    max_sum = 0

    for i in range(1 << rows):
        selected_cells = []
        current_sum = 0

        for row_index in range(rows):
            if (i >> row_index) & 1:
                # Select a cell in this row
                best_col = -1
                for col_index in range(cols):
                    if grid[row_index][col_index] not in [cell[0] for cell in selected_cells]:
                        if best_col == -1 or grid[row_index][col_index] > grid[row_index][best_col]:
                            best_col = col_index

                if best_col != -1:
                    selected_cells.append((grid[row_index][best_col], row_index, best_col))
                    current_sum += grid[row_index][best_col]

